# frozen_string_literal: true

# Inline SVG icons for the portal pages, vendored from the exact packages the
# Node app rendered with so the geometry matches the frozen visual-diff
# baselines:
#   - lucide-react v0.453.0 (ISC license) — path data extracted from
#     node_modules/lucide-react/dist/esm/icons/*.js. Icon geometry drifts
#     between lucide versions; do not "refresh" these from lucide.dev.
#   - react-icons simple-icons set (SiLinkedin), CC0 path data.
#
# The wrapper <svg> attributes replicate each library's React output byte-for-
# byte (lucide: 24×24 stroke icons; react-icons: 1em fill icons) so Tailwind
# sizing classes (w-4 h-4 …) behave identically.
module IconsHelper
  def lucide_icon(name, css: nil)
    inner = LUCIDE.fetch(name)
    klass = [ "lucide", "lucide-#{name}", css ].compact.join(" ")
    <<~SVG.html_safe
      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="#{klass}">#{inner}</svg>
    SVG
  end

  def linkedin_icon(css: nil)
    <<~SVG.html_safe
      <svg stroke="currentColor" fill="currentColor" stroke-width="0" role="img" viewBox="0 0 24 24" class="#{css}" height="1em" width="1em" xmlns="http://www.w3.org/2000/svg"><path d="#{LINKEDIN_PATH}"></path></svg>
    SVG
  end

